import numpy as np
from scipy.optimize import linear_sum_assignment


# Generated by Claude Code
def reference_templates(V, Y):
    V = np.asarray(V, dtype=float)
    Y = np.asarray(Y)
    if V.ndim != 2 or Y.ndim != 2 or Y.shape[1] != V.shape[1]:
        raise ValueError("V and Y must share the time axis")

    Yb = Y.astype(bool)
    only_one = Yb.sum(axis=0) == 1  # frames where exactly one pitch is active
    F, K = V.shape[0], Yb.shape[0]

    R = np.empty((F, K))
    n_frames = np.empty(K, dtype=int)

    for k in range(K):
        mask = Yb[k] & only_one
        n_frames[k] = int(mask.sum())
        if n_frames[k] == 0:
            raise ValueError(f"no single-pitch frames for pitch {k}")
        v_bar = V[:, mask].mean(axis=1)  # mean spectrum over T_k
        R[:, k] = v_bar / v_bar.sum()  # normalize to sum one

    return {
        "R": R,
        "n_frames": n_frames
    }


def cosine_similarity(A, B, eps=1e-12):
    A = np.asarray(A, float)
    B = np.asarray(B, float)

    An = A / np.maximum(np.linalg.norm(A, axis=0, keepdims=True), eps)
    Bn = B / np.maximum(np.linalg.norm(B, axis=0, keepdims=True), eps)

    return An.T @ Bn  # (A.shape[1], B.shape[1])


def match_components(W, R):
    S = cosine_similarity(W, R)

    rows, cols = linear_sum_assignment(S, maximize=True)

    perm = np.empty(R.shape[1], dtype=int)
    perm[cols] = rows  # perm[k] = component assigned to pitch k

    matched = S[perm, np.arange(R.shape[1])]
    used = set(perm.tolist())
    unmatched = [j for j in range(S.shape[0]) if j not in used]

    return {
        "perm": perm,
        "similarity": S,
        "matched": matched,
        "unmatched": unmatched
    }


def activation_scales(H, Y, q=95.0):
    H = np.asarray(H, dtype=float)
    Y = np.asarray(Y).astype(bool)

    if H.shape != Y.shape:
        raise ValueError("H and Y must have the same shape (K, T)")

    K = H.shape[0]
    c = np.empty(K)

    for k in range(K):
        active = H[k, Y[k]]
        if active.size == 0:
            raise ValueError(f"pitch {k} is never active")
        c[k] = np.percentile(active, q)

    return np.maximum(c, 1e-12)
